package com.gameaggregator.publisherservice.domain; import jakarta.persistence.*; import java.util.UUID; @Entity @Table(name="publishers") public class Publisher{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID tenantId;@Column(nullable=false,unique=true)public String slug;@Column(nullable=false)public String name;@Column(nullable=false)public UUID ownerUserId;protected Publisher(){}public Publisher(UUID t,String s,String n,UUID o){tenantId=t;slug=s;name=n;ownerUserId=o;}}
